            new_value = property(func, getattr(value, 'fset', None), 
                               getattr(value, 'fdel', None), getattr(value, '__doc__', None))
            new_value.original = getattr(cls, func_name, None)
            setattr(cls, func_name, new_value)
        else:
            # For regular functions, add attributes to the value itself
            value.__name__ = func_name
            value.original = getattr(cls, func_name, None)
            setattr(cls, func_name, value)
